// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        c.mintToken(address(this), burnAmount);
        uint256 supplyBefore = c.totalSupply();
        vm.prank(address(this));
        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter < supplyBefore);
    }
}
